a11yCss.isHighContrast:
html {
  filter: contrast(150%) brightness(0.8) !important;
}
body {
  background-color: #000000 !important;
  color: #ffff00 !important;
}
main, section, article, header:not([data-accessibility-widget]), footer:not([data-accessibility-widget]) {
  background-color: #000000 !important;
  color: #ffff00 !important;
}
p, span, h1, h2, h3, h4, h5, h6, li, label, td, th {
  color: #ffff00 !important;
}
a:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  color: #00ffff !important;
  text-decoration: underline !important;
}
button:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: #000000 !important;
  color: #ffff00 !important;
  border: 2px solid #ffff00 !important;
}
input:not([data-accessibility-widget] *),
select:not([data-accessibility-widget] *),
textarea:not([data-accessibility-widget] *) {
  background-color: #000000 !important;
  color: #ffff00 !important;
  border: 2px solid #ffff00 !important;
}
img, video {
  filter: contrast(100%) brightness(1.2) !important;
}
/* Exclude accessibility widget completely */
[data-accessibility-widget] {
  filter: none !important;
}
[data-accessibility-widget] * {
  background-color: inherit !important;
  color: inherit !important;
  filter: none !important;
  border-color: inherit !important;
}

a11yCss.isNegativeContrast:
html {
  filter: invert(100%) hue-rotate(180deg) !important;
}
img, video, iframe {
  filter: invert(100%) hue-rotate(180deg) !important;
}

a11yCss.isLightBackground:
body {
  background-color: #ffffff !important;
  color: #000000 !important;
}
main, section, article, header:not([data-accessibility-widget]), footer:not([data-accessibility-widget]) {
  background-color: #ffffff !important;
  color: #000000 !important;
}
/* Override dark background gradient classes */
[class*="bg-gray-950"], [class*="bg-gray-900"], [class*="bg-gray-800"],
[class*="from-gray-950"], [class*="from-gray-900"], [class*="via-gray-900"], [class*="via-gray-950"],
[class*="to-gray-950"], [class*="to-gray-900"] {
  background-color: #ffffff !important;
  background-image: none !important;
}
/* Keep gradient overlays on images transparent - CRITICAL */
[class*="absolute"][class*="bg-gradient"],
[class*="absolute"][class*="from-gray"],
[class*="absolute"][class*="via-gray"],
[class*="absolute"][class*="to-gray"],
[class*="inset"][class*="bg-gradient"],
[class*="inset"][class*="from-gray"],
img ~ [class*="bg-gradient"],
picture ~ [class*="bg-gradient"],
video ~ [class*="bg-gradient"],
[class*="bg-gradient-to-t"][class*="absolute"],
[class*="bg-gradient-to-b"][class*="absolute"],
[class*="bg-gradient-to-r"][class*="absolute"],
[class*="bg-gradient-to-l"][class*="absolute"] {
  background-color: transparent !important;
  background-image: none !important;
  opacity: 0.1 !important;
}
p:not([data-accessibility-widget] *),
span:not([data-accessibility-widget] *),
h1:not([data-accessibility-widget] *),
h2:not([data-accessibility-widget] *),
h3:not([data-accessibility-widget] *),
h4:not([data-accessibility-widget] *),
h5:not([data-accessibility-widget] *),
h6:not([data-accessibility-widget] *),
li:not([data-accessibility-widget] *),
label:not([data-accessibility-widget] *),
td:not([data-accessibility-widget] *),
th:not([data-accessibility-widget] *),
strong:not([data-accessibility-widget] *),
em:not([data-accessibility-widget] *),
b:not([data-accessibility-widget] *),
i:not([data-accessibility-widget] *) {
  color: #000000 !important;
}
[class*="text-white"]:not([data-accessibility-widget] *):not([data-accessibility-widget]) {
  color: #000000 !important;
}
a:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  color: #0000ee !important;
  text-decoration: underline !important;
}
button:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: #ffffff !important;
  color: #000000 !important;
  border: 1px solid #000000 !important;
}
input:not([data-accessibility-widget] *),
select:not([data-accessibility-widget] *),
textarea:not([data-accessibility-widget] *) {
  background-color: #ffffff !important;
  color: #000000 !important;
  border: 1px solid #000000 !important;
}
[class*="Card"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="card"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: #ffffff !important;
  color: #000000 !important;
  border-color: #cccccc !important;
}
.backface-hidden:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="backface"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: #ffffff !important;
  color: #000000 !important;
}
.backface-hidden .bg-gray-900,
.backface-hidden .bg-black,
.backface-hidden [class*="bg-black"],
.backface-hidden [class*="bg-gray-900"],
.backface-hidden [class*="bg-gray-800"],
[class*="backface"] .bg-gray-900,
[class*="backface"] .bg-black,
[class*="backface"] [class*="bg-black"],
[class*="backface"] [class*="bg-gray-900"],
[class*="backface"] [class*="bg-gray-800"] {
  background-color: #ffffff !important;
  background-image: none !important;
  opacity: 1 !important;
}
.backface-hidden [class*="bg-gradient"],
[class*="backface"] [class*="bg-gradient"] {
  background-color: #ffffff !important;
  background-image: none !important;
  opacity: 1 !important;
}
.backface-hidden p,
.backface-hidden span,
.backface-hidden h1,
.backface-hidden h2,
.backface-hidden h3,
.backface-hidden h4,
.backface-hidden h5,
.backface-hidden h6,
.backface-hidden div,
[class*="backface"] p,
[class*="backface"] span,
[class*="backface"] h1,
[class*="backface"] h2,
[class*="backface"] h3,
[class*="backface"] h4,
[class*="backface"] h5,
[class*="backface"] h6,
[class*="backface"] div {
  color: #000000 !important;
}
.backface-hidden [class*="text-white"],
[class*="backface"] [class*="text-white"] {
  color: #000000 !important;
}
[style*="rotateY(180deg)"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: #ffffff !important;
  color: #000000 !important;
}
[style*="rotateY(180deg)"] *:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  color: #000000 !important;
}
[style*="rotateY(180deg)"] .bg-gray-900,
[style*="rotateY(180deg)"] .bg-black,
[style*="rotateY(180deg)"] [class*="bg-black"],
[style*="rotateY(180deg)"] [class*="bg-gray"] {
  background-color: #ffffff !important;
  background-image: none !important;
  opacity: 1 !important;
}
[style*="rotateY(180deg)"] [class*="bg-gradient"] {
  background-color: #ffffff !important;
  background-image: none !important;
  opacity: 1 !important;
}
img:not([data-accessibility-widget]):not([data-accessibility-widget] *),
picture:not([data-accessibility-widget]):not([data-accessibility-widget] *),
svg:not([data-accessibility-widget]):not([data-accessibility-widget] *),
video:not([data-accessibility-widget]):not([data-accessibility-widget] *),
iframe:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  opacity: 1 !important;
  visibility: visible !important;
  display: block !important;
  filter: none !important;
  background-color: transparent !important;
  background-image: none !important;
  z-index: 1 !important;
}
[class*="Image"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="image"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="next-image"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
span[class*="Image"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  opacity: 1 !important;
  visibility: visible !important;
  display: block !important;
  background-color: transparent !important;
}
div img:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div picture:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="Image"] img:not([data-accessibility-widget]):not([data-accessibility-widget] *),
span[class*="Image"] img:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  opacity: 1 !important;
  visibility: visible !important;
  display: block !important;
  background-color: transparent !important;
  z-index: 20 !important;
}
div[class*="relative"]:has(img):not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: transparent !important;
}
div:has(> img):not([data-accessibility-widget]):not([data-accessibility-widget] *),
div:has(> picture):not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: transparent !important;
}
div[class*="bg-gray-950/90"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="bg-gray-950"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: transparent !important;
  background-image: none !important;
}
div[class*="absolute"][class*="bottom-0"][class*="bg-gradient-to-t"][class*="from-gray-950"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="absolute"][class*="bottom-0"][class*="via-gray-950"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: rgba(255, 255, 255, 0.3) !important;
  background-image: linear-gradient(to top, rgba(255, 255, 255, 0.5), transparent) !important;
  opacity: 0.7 !important;
}
div[class*="relative"][class*="overflow-hidden"] img:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="relative"][class*="overflow-hidden"] picture:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="relative"][class*="overflow-hidden"] [class*="Image"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="relative"][class*="overflow-hidden"] span img:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  z-index: 30 !important;
  position: relative !important;
  opacity: 1 !important;
  visibility: visible !important;
}
div[class*="relative"][class*="w-full"][class*="h-full"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="absolute"][class*="inset-0"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="absolute"][class*="inset-0"][class*="flex"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: transparent !important;
}
div[class*="absolute"][class*="bottom-0"][class*="left-0"][class*="right-0"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  background-color: rgba(255, 255, 255, 0.4) !important;
  background-image: linear-gradient(to top, rgba(255, 255, 255, 0.6), transparent) !important;
  opacity: 0.8 !important;
  z-index: 20 !important;
}
div[class*="absolute"][class*="bottom-0"] h3:not([data-accessibility-widget]):not([data-accessibility-widget] *),
div[class*="absolute"][class*="bottom-0"] p:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  color: #000000 !important;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.8) !important;
}
[data-accessibility-widget] {
  background-color: inherit !important;
  filter: none !important;
}
[data-accessibility-widget] * {
  background-color: inherit !important;
  color: inherit !important;
  filter: none !important;
  border-color: inherit !important;
}

a11yCss.isLinksUnderlined:
a:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  text-decoration: underline !important;
  background-color: #ffff00 !important;
  color: #000000 !important;
  font-weight: bold !important;
  padding: 0 2px !important;
}

a11yCss.isHighlightTitles:
h1:not([data-accessibility-widget] *),
h2:not([data-accessibility-widget] *),
h3:not([data-accessibility-widget] *),
h4:not([data-accessibility-widget] *),
h5:not([data-accessibility-widget] *),
h6:not([data-accessibility-widget] *) {
  background-color: #000000 !important;
  color: #ffffff !important;
  padding: 5px 10px !important;
  display: inline-block !important;
  margin: 5px 0 !important;
  border-radius: 0 !important;
}

a11yCss.isLargeCursor:
html, body, a, button, input, select, textarea {
  cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewport="0 0 48 48" style="fill:black;stroke:white;stroke-width:2px;"><path d="M0,0 L0,36 L8.5,25.5 L19,48 L24,45 L13.5,23.5 L24,24 L0,0 Z"/></svg>'), auto !important;
}

a11yCss.isTextSpacing:
* {
  line-height: 1.8 !important;
  letter-spacing: 0.1em !important;
  word-spacing: 0.2em !important;
}
p, li, h1, h2, h3, h4, h5, h6 {
  margin-bottom: 1.5em !important;
}
.backface-hidden:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="backface"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  overflow: auto !important;
  overflow-x: hidden !important;
  min-height: fit-content !important;
  max-height: none !important;
}
[class*="perspective"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  min-height: fit-content !important;
  height: auto !important;
}
[class*="preserve-3d"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  height: auto !important;
  min-height: 400px !important;
}
div:has(.backface-hidden):not([data-accessibility-widget]):not([data-accessibility-widget] *),
div:has([class*="backface"]):not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  height: auto !important;
  min-height: 400px !important;
}
.backface-hidden > div:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="backface"] > div:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  min-height: fit-content !important;
  height: auto !important;
  max-height: none !important;
}
.backface-hidden [class*="flex"]:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="backface"] [class*="flex"]:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  min-height: fit-content !important;
  flex-wrap: wrap !important;
}
.backface-hidden p:not([data-accessibility-widget]):not([data-accessibility-widget] *),
[class*="backface"] p:not([data-accessibility-widget]):not([data-accessibility-widget] *) {
  margin-bottom: 1em !important;
}

a11yCss.areAnimationsStopped:
*:not([data-accessibility-widget]):not([data-accessibility-widget] *),
*:not([data-accessibility-widget])::before,
*:not([data-accessibility-widget])::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}
